from usg.dsl import *

# Find the signalised crossing
crossings = MAP.crossings(control=None) or MAP.crossings()
signalised = [c for c in crossings if c.get("signal_id")]
if not signalised:
    raise ValueError("No signalised crossing found")
cid, sig_id = signalised[0]["id"], signalised[0]["signal_id"]
road = MAP.road(crossings[0]["road"])

scenario = ScenarioBuilder("cross_with_traffic", MAP, scenario_type="dyn_nav",
                           description="Cross on green while a car approaches.")
scenario.user(MAP.crossing_side(cid, "start", inset=2.0))

# Create the signal cycle
signal_name = scenario.signal_cycle(cid, green=15, red=20, initial="red")

# Create the approaching car
s_from = float(crossings[0]["road_s"])
s_to = min(road["length"], s_from + 30.0)
route = MAP.drive_route(road, s_from, s_to, "forward")
scenario.vehicle("Car1", route[0], route[1:], speed=8.0, model="car_white", start_when=when_task_starts(None))

handles = scenario.apply_spec({
    "tasks": [{
        "name": "cross_with_traffic",
        "instruction": "Check the traffic, then cross on green.",
        "goal": {
            "op": "call",
            "name": "cross",
            "args": {
                "far_zone": {
                    "kind": "crossing_side",
                    "id": cid,
                    "side": "end",
                    "inset": 1.0,
                    "r": 1.5
                }
            }
        },
        "safety": [
            {
                "op": "call",
                "name": "collision_free",
                "args": {
                    "entity": "Car1",
                    "r": 0.3
                }
            },
            {
                "op": "call",
                "name": "obey_signal",
                "args": {
                    "zone": {
                        "kind": "crossing",
                        "id": cid
                    },
                    "signal": sig_id
                }
            }
        ],
        "timeout": {
            "initial": 60.0,
            "baseline": 90.0
        }
    }]
})
